// Gives /lists, /majors and /precons links a rich preview when shared (title,
// description, and a character-card image) instead of the generic site card. The
// tags themselves are injected by lib/og-tags.js.
//
// Preview text/images come from netlify/edge-functions/lib/preview-data.js,
// generated by scripts/gen-preview-manifest.mjs.

import manifest, { SITE_BASE } from './lib/preview-data.js'
import { withPreviewTags } from './lib/og-tags.js'

export const config = { path: ['/lists/*', '/majors/*', '/precons', '/precons/*'] }

// Map a /lists or /majors pathname to its preview entry, or null when there's
// nothing richer than the site default to show. The two sections have the same
// URL shape (index / :event / :event/:id) but separate manifest namespaces.
function lookup(pathname) {
  const parts = pathname.replace(/^\/+|\/+$/g, '').split('/')

  // /precons and /precons/:deck — one level shallower, its own namespace.
  if (parts[0] === 'precons') {
    if (parts.length === 1) return manifest.precons?.index || null
    if (parts.length === 2) return manifest.precons?.decks?.[decodeURIComponent(parts[1])] || null
    return null
  }

  const section = parts[0] === 'lists'
    ? manifest
    : parts[0] === 'majors'
      ? manifest.majors
      : null
  if (!section) return null

  if (parts.length === 1) return section.index || null
  const event = decodeURIComponent(parts[1])
  if (parts.length === 2) return section.events?.[event] || null
  const standing = decodeURIComponent(parts[2])
  return section.players?.[`${event}/${standing}`] || null
}

export default async (request, context) => {
  const res = await context.next()
  const url = new URL(request.url)
  return withPreviewTags(res, lookup(url.pathname), SITE_BASE + url.pathname)
}
